import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return no living cells for an empty grid");
  it.todo("should let a single living cell die of underpopulation");
  it.todo("should let two adjacent living cells die of underpopulation");
  it.todo("should let a living cell with three neighbors survive");
  it.todo("should let a living cell with four neighbors die of overpopulation");
  it.todo("should bring a dead cell with exactly three neighbors to life");
  it.todo("should oscillate a vertical blinker into a horizontal blinker");
  it.todo("should keep a block unchanged as a still life");
  it.todo("should handle cells at negative coordinates");
});
